void cFractalInvspherer100::FormulaCode(
	CVector4 &z, const sFractal *fractal, sExtendedAux &aux)
{
	// Sphere inversion
	CVector3 center = CVector3(0, 0, 0);
	CVector3 offset = CVector3(0, 0, 0);
	
	// Pre-offset
	z += offset;
	
	// Inversion
	double rr = z.Dot(z);
	double invRadius = 1.0;
	
	if (rr > 0.0001) // Guard against division by zero
	{
		double factor = invRadius / rr;
		z *= factor;
		aux.DE *= factor;
	}
	
	// Post-offset and scale
	z -= offset;
	z *= 1.0;
	aux.DE *= 1.0;
}
